-- Candidates/db/seed/precinct_polygons_albany_seed.sql
-- Albany County current precinct polygons from ElectionGeography_public ArcGIS FeatureServer.
-- Source: junverzagt_AlbanyGIS (albanygis.maps.arcgis.com). Live post-redistricting data.
-- Vote center model: any voter may use any of the 10 vote centers.
-- pollingid (GUID) links precincts to Voting Locations via GlobalID.
-- Precincts with no pollingid use nearest-center by haversine from centroid.
-- Replaces 27-row 2020 Census TIGER VTD seed.

DELETE FROM precinct_polygons WHERE LOWER(county) = 'albany';

